"""Basic workbook reading examples for the bundled xlrd-compatible API."""

from __future__ import print_function

import sys

import xlrd


def main(path):
    book = xlrd.open_workbook(path, formatting_info=True)
    print("Workbook:", path)
    print("Sheets:", book.sheet_names())

    for sheet in book:
        print("Sheet:", sheet.name, "size=", (sheet.nrows, sheet.ncols))
        for rowx in range(sheet.nrows):
            print(" ", sheet.row_values(rowx))


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python examples/basic_usage.py <workbook.xls>")
    main(sys.argv[1])

