"""Small command-line helpers for inspecting and reading ``.xls`` workbooks."""

from __future__ import print_function

import argparse
import json
import sys

from . import FILE_FORMAT_DESCRIPTIONS, XLRDError, inspect_format, open_workbook


def _sheet_payload(sheet, limit_rows=None):
    if limit_rows is None:
        row_indexes = range(sheet.nrows)
    else:
        row_indexes = range(min(limit_rows, sheet.nrows))
    return {
        "name": sheet.name,
        "nrows": sheet.nrows,
        "ncols": sheet.ncols,
        "rows": [sheet.row_values(rowx) for rowx in row_indexes],
    }


def build_parser():
    parser = argparse.ArgumentParser(
        prog="python -m xlrd",
        description="Inspect and read historical Excel .xls workbooks.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    inspect_parser = subparsers.add_parser(
        "inspect",
        help="detect the container format for a path",
    )
    inspect_parser.add_argument("path", help="path to a spreadsheet or archive")

    overview_parser = subparsers.add_parser(
        "overview",
        help="open a workbook and print basic workbook metadata as JSON",
    )
    overview_parser.add_argument("path", help="path to an .xls workbook")

    rows_parser = subparsers.add_parser(
        "rows",
        help="open a workbook and print rows from one sheet as JSON",
    )
    rows_parser.add_argument("path", help="path to an .xls workbook")
    rows_parser.add_argument(
        "--sheet",
        default=0,
        help="sheet index or sheet name to read (default: 0)",
    )
    rows_parser.add_argument(
        "--limit",
        type=int,
        default=None,
        help="maximum number of rows to return",
    )

    return parser


def _resolve_sheet(book, sheet_reference):
    try:
        sheet_index = int(sheet_reference)
    except (TypeError, ValueError):
        return book.sheet_by_name(sheet_reference)
    return book.sheet_by_index(sheet_index)


def main(argv=None):
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        if args.command == "inspect":
            file_format = inspect_format(path=args.path)
            payload = {
                "path": args.path,
                "format": file_format,
                "description": FILE_FORMAT_DESCRIPTIONS[file_format],
            }
        elif args.command == "overview":
            book = open_workbook(args.path)
            payload = {
                "filename": book.filename,
                "nsheets": book.nsheets,
                "sheet_names": book.sheet_names(),
                "sheets": [
                    {
                        "name": sheet.name,
                        "nrows": sheet.nrows,
                        "ncols": sheet.ncols,
                    }
                    for sheet in book
                ],
            }
        else:
            book = open_workbook(args.path)
            sheet = _resolve_sheet(book, args.sheet)
            payload = _sheet_payload(sheet, limit_rows=args.limit)
    except (FileNotFoundError, IndexError, XLRDError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        return 2

    print(json.dumps(payload, indent=2, sort_keys=True, default=str))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

